@Test
	public void expectedLongFoundNothing() {
		assertParsingResult(OBJECT_LONG_DEFAULT, new BaseParser() {
			@Override
			Object parseOneLine(QuerySolution solution) {
				return ifLongPresent(solution, "nothing", OBJECT_LONG_DEFAULT);
			}
		});
	}

